def can_chain(dominoes):
    """Return a closed chain of dominoes, or None if no chain exists.

    A valid chain uses every domino exactly once (reversing a domino is
    allowed), has matching halves between adjacent dominoes, and the open
    ends of the chain match each other.
    """
    if not dominoes:
        return []

    def backtrack(remaining, chain):
        if not remaining:
            # The chain closes only if the open ends match.
            if chain[0][0] == chain[-1][1]:
                return chain
            return None

        end = chain[-1][1]
        for i, (a, b) in enumerate(remaining):
            for first, second in ((a, b), (b, a)):
                if first != end:
                    continue
                rest = remaining[:i] + remaining[i + 1:]
                result = backtrack(rest, chain + [(second, first)])
                if result is not None:
                    return result
        return None

    for i, (a, b) in enumerate(dominoes):
        for first, second in ((a, b), (b, a)):
            rest = dominoes[:i] + dominoes[i + 1:]
            result = backtrack(rest, [(first, second)])
            if result is not None:
                return result
    return None

